module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

reg [15:0] a_reg;
reg [15:0] b_reg;
reg [15:0] result;
reg [15:0] odd;

always @(A or B) begin
    a_reg <= A;
    b_reg <= B;
end

always @(A or B) begin
    if (a_reg >= b_reg) begin
        a_reg <= a_reg - b_reg + 1'b1;
        b_reg <= b_reg;
    end
    else begin
        a_reg <= a_reg;
        b_reg <= b_reg;
    end
end

assign odd = a_reg;
assign result = a_reg / b_reg;

endmodule
